# -*- coding: utf-8 -*-
"""positionclose - MT4 version (replaces OANDA)"""

import sys
import os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from baserequest import BaseRequest

class Units:
    """Units wrapper for MT4 (replaces OANDA)"""
    def __init__(self, units):
        self.value = str(units)


class PositionCloseRequest(BaseRequest):
    """create a PositionCloseRequest.

    PositionCloseRequest is used to build the body to close a position.
    The body can be used to pass to the PositionClose endpoint.
    
    For MT4, closing positions is handled via the ticket number.
    This class now serves as a data structure for position close parameters.
    """

    def __init__(self,
                 longUnits=None,
                 longClientExtensions=None,
                 shortUnits=None,
                 shortClientExtensions=None,
                 ticket=None,
                 instrument=None):
        """
        Instantiate a PositionCloseRequest.

        Parameters
        ----------

        longUnits : integer (optional)
            the number of long units to close (for MT4, use ticket instead)

        longClientExtensions : dict (optional)
            dict representing longClientExtensions

        shortUnits : integer (optional)
            the number of short units to close (for MT4, use ticket instead)

        shortClientExtensions : dict (optional)
            dict representing shortClientExtensions
            
        ticket : integer (optional - MT4 specific)
            the MT4 ticket number of the position to close

        instrument : string (optional - MT4 specific)
            the instrument symbol (e.g., 'EURUSD')

        One of the parameters must be supplied.

        Example
        -------
        
        >>> from mt4_position_requests import PositionCloseRequest
        >>> from mt4_price_provider import get_mt4_prices
        >>>
        >>> # For MT4, close by ticket number
        >>> close_request = PositionCloseRequest(ticket=12345)
        >>> 
        >>> # Then execute via MT4 client:
        >>> mt4 = get_mt4_prices()
        >>> result = mt4.close_position(12345)
        >>> print(result)
        """
        super(PositionCloseRequest, self).__init__()

        # For MT4 compatibility - allow closing by ticket
        if ticket:
            self._data.update({"ticket": ticket})
        if instrument:
            self._data.update({"instrument": instrument})

        # Keep original interface for backward compatibility
        if not (longUnits or shortUnits or ticket):
            raise ValueError("longUnits, shortUnits, or ticket parameter required")

        if longUnits:
            self._data.update({"longUnits": Units(longUnits).value})

            if longClientExtensions:
                self._data.update({"longClientExtensions":
                                   longClientExtensions})

        if shortUnits:
            self._data.update({"shortUnits": Units(shortUnits).value})

            if shortClientExtensions:
                self._data.update({"shortClientExtensions":
                                   shortClientExtensions})

    @property
    def data(self):
        """data property.
        
        return the JSON order body for MT4
        """
        return dict({"positionClose": super(PositionCloseRequest, self).data})


# ============ MT4 Position Close Helper ============

class MT4PositionCloser:
    """
    Helper class to close positions in MT4 (replaces OANDA position close)
    """
    
    def __init__(self):
        from mt4_price_provider import get_mt4_prices
        self.mt4 = get_mt4_prices()
    
    def close_by_ticket(self, ticket):
        """
        Close a position by MT4 ticket number
        
        Parameters
        ----------
        ticket : integer
            the MT4 ticket number of the position to close
            
        Returns
        -------
        dict
            result of the close operation
        """
        return self.mt4.close_position(ticket)
    
    def close_by_instrument(self, instrument, units=None):
        """
        Close a position by instrument (closes all or specified units)
        
        Parameters
        ----------
        instrument : string
            the instrument symbol (e.g., 'EURUSD')
        units : integer, optional
            number of units to close (closes all if not specified)
            
        Returns
        -------
        dict
            result of the close operation
        """
        # Get all open positions
        positions = self.mt4.get_positions()
        
        if not positions or 'positions' not in positions:
            return {'success': False, 'error': 'No positions found'}
        
        # Find position matching the instrument
        mt4_symbol = instrument.replace('/', '_')
        for pos in positions.get('positions', []):
            if pos.get('symbol') == mt4_symbol:
                ticket = pos.get('ticket')
                if ticket:
                    return self.close_by_ticket(ticket)
        
        return {'success': False, 'error': f'No position found for {instrument}'}
    
    def close_all_positions(self):
        """Close all open positions"""
        positions = self.mt4.get_positions()
        results = []
        
        if not positions or 'positions' not in positions:
            return {'success': False, 'error': 'No positions found', 'closed': 0}
        
        for pos in positions.get('positions', []):
            ticket = pos.get('ticket')
            if ticket:
                result = self.close_by_ticket(ticket)
                results.append(result)
        
        return {
            'success': True,
            'closed': len(results),
            'results': results
        }


# Global instance for easy access
_mt4_closer = None

def get_mt4_position_closer():
    """Get the global MT4 position closer instance"""
    global _mt4_closer
    if _mt4_closer is None:
        _mt4_closer = MT4PositionCloser()
    return _mt4_closer
